import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:19.5px;line-height:1.26}.box h2{font-size:25px;margin-bottom:5px}.tbl{font-size:18px}.note,.warn{font-size:17px}.tbl th,.tbl td{padding:3px 6px}.iq ol{font-size:19px;line-height:1.26}.pill{font-size:16px}.grid{gap:12px}.handle{bottom:-12px}.box{padding:11px 13px}.tagline{font-size:19px;margin-bottom:9px}.code{font-family:Consolas,'DejaVu Sans Mono',monospace;background:#f1f5f9;border:1px dashed #94a3b8;border-radius:6px;padding:5px 7px;margin:4px 0;line-height:1.3;font-size:16px}</style>
<div class="title">🛤️ HxGN EAM Linear Equipment <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">Roads, rail, pipelines: assets with a length, where work happens "from mile 6 to 7", not on the whole asset. (Infor EAM 11.7 Linear Equipment brief)</div>
<div class="grid">
<div class="box c1"><h2>1. What makes it linear</h2><ul><li>Assets, Positions, Systems can be linear</li><li><b>Equipment Length + UOM</b> (m, km, ft, mi)</li><li><b>Linear Reference UOM</b>: km road, features in metres</li><li><b>From Point</b> shifts everything: a 10-mile road starting at marker 65 shows mile 1 as 66</li></ul></div>
<div class="box c2"><h2>2. Linear Equipment Type (LETP)</h2><table class="tbl"><tr><th>Type</th><th>Example</th></tr><tr><td><b>RTOW</b> Right of Way</td><td>Interstate 40</td></tr><tr><td><b>ROUT</b> Route</td><td>Eastbound lane, track 1</td></tr><tr><td><b>SEGM</b> Segment</td><td>Smallest piece; a switch can be a point</td></tr></table><div class="warn">Type and Direction (LDIR) go together. Leave both blank and you lose offsets + Trace.</div></div>
<div class="box c3"><h2>3. Linear References tab (LRTP)</h2><ul><li><b>Linear Reference System</b>: mileposts, markers</li><li><b>Point of Interest</b>: one-off, e.g. welcome center</li><li><b>Related Equipment</b>: bus stop, bridge, culvert</li><li><b>Related Part</b>: ties, gravel, cable</li><li>Class (entity LREF) groups rows on the overview</li></ul></div>
<div class="box c4"><h2>4. Locating a feature</h2><ul><li>From / To Point, 0 to 6 decimals</li><li>From Reference (a milepost) + Offset / Offset % + Offset Direction</li><li>Point Reference: To = From</li><li>X/Y, Lat/Long, horizontal + vertical offsets</li></ul><div class="code">milepost 5290 ft + 25 ft North = 5315 ft</div></div>
<div class="box c5"><h2>5. Smart data entry</h2><ul><li><b>Repeat Every Length</b>: 5,000 ft asset, start 1,500, every 1,000 → 4 rows (1,500 / 2,500 / 3,500 / 4,500), one Set ID</li><li><b>Apply to Children</b> / <b>Apply to Route/ROW</b>: define once</li><li><b>Split</b> (2 parts) and <b>Insert Inside</b> (3 parts) expire the old row, history kept</li></ul></div>
<div class="box c6"><h2>6. Condition + Overview</h2><ul><li><b>Linear Condition</b> tab: Condition, Risk Priority, Criticality scores/index, colors from Equipment Ranking</li><li><b>Linear Overview</b>: graphical bar, needs Display on Overview <b>and</b> Class</li><li>Filter WOs, Inspections, Nonconformities, Checklists; Effective date = past view</li><li>Dataspy shows first 500 only</li></ul></div>
<div class="box c7"><h2>7. Segments, Routes, Branches</h2><ul><li>Segments tab only on a Route; Routes tab only on a Right of Way</li><li><b>Branch Point</b> pairs (same Equipment or Branch Identifier) = crossover</li><li><b>SRSTSYNC</b> I / D / ID keeps structure in sync</li><li>Linear Cost Weight (Systems): weight 2 vs 1 → 2/3 vs 1/3 of cost</li></ul></div>
<div class="box c8"><h2>8. Linear work orders</h2><ul><li>WO From/To Point within the asset; activities within the WO range</li><li>Reference Points against direction? EAM swaps From/To on save</li><li>Equipment, Checklist, Inspections tabs + Deferred Maintenance carry From/To</li><li><b>WOFUFPTP</b>=NO: one follow-up WO per From/To combo</li></ul></div>
<div class="box c1" style="grid-column:1 / span 2"><h2>9. Trace Route + linear PMs</h2><table class="tbl"><tr><th>Feature</th><th>What it does</th></tr><tr><td><b>Trace Route</b> popup</td><td>Pick a route + From/To, Add To List, cross over via branch points, Continue Trace / New Trace, Add all Routes of Right of Way, Add Related Equipment, Submit</td></tr><tr><td><b>MEC Work Orders</b> flag</td><td>Ticked: Multi-Equipment Child WOs; else regular child WOs. Copy Activities optional</td></tr><tr><td><b>TRACELEV</b></td><td>ROUTE = one child WO per route · SEGMENT = one per segment touched (more WOs)</td></tr><tr><td><b>Breakdown Linear Work</b> (PM Schedules)</td><td>Add the asset with From/To on the Equipment tab, then split it into smaller sections; save generates Equipment tab rows</td></tr></table></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">10a. Setup flow</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Linear Direction Setup (pairs)</span><span class="arr">→</span><span class="pill">Classes OBJ + LREF</span><span class="arr">→</span><span class="pill">Right of Way / Route / Segment</span><span class="arr">→</span><span class="pill">Linear References</span><span class="arr">→</span><span class="pill">Linear WO / PM</span><span class="arr">→</span><span class="pill">Linear Overview</span></div></div>
<div class="box iq"><h2>10b. Consultant tips</h2><ol><li>Set Type + Direction on day one</li><li>Predefine references on the Class</li><li>Use Random Results for linear inspection aspects</li><li>ALTPOINT=PLUS100 shows 123+45 stationing</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">10c. Key points</h2><ul><li>Work on any slice of the asset</li><li>History via Effective / Expired</li><li>Branch points drive tracing</li></ul></div>
</div></div>'''
build("/workspace/instagram-assets/posts/2026-10-27-linkedin-eam-linear-equipment",B,1620,"Rahul Kumar")
